import os
import shutil

from delta.tables import DeltaTable
from pyspark.errors import AnalysisException
from pyspark.sql import functions as F

LANDING = "/tmp/landing"
TARGET = "/tmp/silver/shipment_events"


class Carrier:
    # Stands in for the carrier's uploads: one landing folder per load day. Don't change this.
    # Night 1: every day has landed except the 2nd, which lands after 2 waits, and the 3rd, which doesn't land that night.
    # Night 2: every day has landed.
    def __init__(self, events, days, night):
        self.events, self.days, self.night, self.waits = events, days, night, 0
        for i, day in enumerate(days):
            if (night == 2 or i not in (1, 2)) and not os.path.exists(self.folder(day)):
                self._land(day)

    def folder(self, day):
        return f"{LANDING}/{day}"

    def _land(self, day):
        self.events.filter(F.col("load_date") == day).write.parquet(self.folder(day))

    def wait(self):
        # Stands in for sleeping before a retry, so the examples don't really wait.
        self.waits += 1
        if self.night == 1 and self.waits == 2 and len(self.days) > 1:
            self._land(self.days[1])


def high_water_mark():
    # The newest load day the target already has, or None before the first run. Don't change this.
    if not DeltaTable.isDeltaTable(spark, TARGET):
        return None
    return spark.read.format("delta").load(TARGET).select(F.max("load_date")).first()[0]


def read_day(carrier, day):
    # Reads one day's landing folder.
    return spark.read.parquet(carrier.folder(day))


def run_night(carrier, days, night):
    # Loads, in date order, the days after the high-water mark, tagging each row with the night that loaded it.
    mark = high_water_mark()
    for day in days:
        if mark is not None and day <= mark:
            continue
        batch = read_day(carrier, day)
        batch.select("event_id", "shipment_id", "event_type", "load_date", F.lit(night).alias("run")).write.format("delta").mode("append").save(TARGET)


def solve(shipment_events):
    shutil.rmtree(LANDING, ignore_errors=True)  # start from empty folders on every run
    shutil.rmtree(TARGET, ignore_errors=True)
    days = sorted(row["load_date"] for row in shipment_events.select("load_date").distinct().collect())
    for night in (1, 2):
        run_night(Carrier(shipment_events, days, night), days, night)
    if not DeltaTable.isDeltaTable(spark, TARGET):
        return spark.createDataFrame([], "event_id STRING, shipment_id STRING, event_type STRING, load_date DATE, run INT")
    return spark.read.format("delta").load(TARGET)
